import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Six explicit battle roots and their four actual controlled HP ports. Numerical bodies remain original. */
public final class SourceControlledDisplayMethods {
 static final String P="local/lito381/server/",PC=P+"ClientSession",N=P+"NativeSourceControlledDisplay",AREA=P+"NativeAreaMaterialAction",CTX=AREA+"$Context";
 static final List<String> TARGETS=List.of(PC,AREA,CTX,P+"BattleCompanion",P+"NativeCompanionPlacement$State",P+"NativeShockCompanionAction",P+"CombatCompanionSpells");
 static final Map<String,String> ROOTS=Map.of("nativeSourceLightningOriginalBody","(L"+P+"Protocol$AttackSpellRequest;L"+P+"BattleSpellCatalog$DirectionalLineSpell;)V","nativeAreaFreezeOriginalBattle","([BL"+P+"BattleSpellCatalog$FreezeAttackSpell;)V","attack","(L"+P+"Protocol$AttackRequest;L"+PC+"$AttackEnvelope;)V","nativeFreezeAcceptedOriginalBattle","([BL"+P+"BattleSpellCatalog$FreezeAttackSpell;)V","useHealingSpell","([BL"+P+"BattleSpellCatalog$HealingSpell;)V","useAttackSpell","(L"+P+"Protocol$AttackSpellRequest;L"+P+"BattleSpellCatalog$AttackSpell;IIII)V","useAreaAttackSpell","(L"+P+"Protocol$AttackSpellRequest;L"+P+"BattleSpellCatalog$AreaAttackSpell;)V","useCenteredAreaAttackSpell","([BL"+P+"BattleSpellCatalog$AreaAttackSpell;)V");
 static boolean root(MethodNode m){return m.desc.equals(ROOTS.get(m.name));}
 static void wrapper(ClassNode c,MethodNode old){String name=old.name;int access=old.access;old.name="nativeSourceControlledOriginal_"+name;old.access=0;var w=new MethodNode(access,name,old.desc,null,old.exceptions.toArray(String[]::new));var x=w.instructions;x.add(new VarInsnNode(ALOAD,0));var args=Type.getArgumentTypes(old.desc);x.add(new LdcInsnNode(args.length));x.add(new TypeInsnNode(ANEWARRAY,"java/lang/Object"));int slot=1;for(int i=0;i<args.length;i++){x.add(new InsnNode(DUP));x.add(new LdcInsnNode(i));x.add(new VarInsnNode(args[i].getOpcode(ILOAD),slot));if(args[i].getSort()==Type.INT)x.add(new MethodInsnNode(INVOKESTATIC,"java/lang/Integer","valueOf","(I)Ljava/lang/Integer;",false));else if(args[i].getSort()!=Type.OBJECT&&args[i].getSort()!=Type.ARRAY)throw new AssertionError("unexpected typed root argument");x.add(new InsnNode(AASTORE));slot+=args[i].getSize();}x.add(new LdcInsnNode(old.name));x.add(new LdcInsnNode(old.desc));x.add(new InsnNode(name.equals("attack")?ICONST_1:ICONST_0));x.add(new MethodInsnNode(INVOKESTATIC,N,"enter","(L"+PC+";[Ljava/lang/Object;Ljava/lang/String;Ljava/lang/String;Z)V",false));x.add(new InsnNode(RETURN));c.methods.add(w);}
 static void guard(MethodNode m){var x=new InsnList();x.add(new VarInsnNode(ALOAD,0));x.add(new VarInsnNode(ALOAD,1));x.add(new MethodInsnNode(INVOKESTATIC,N,"allowFrame","(L"+PC+";[B)Z",false));var pass=new LabelNode();x.add(new JumpInsnNode(IFNE,pass));x.add(new InsnNode(RETURN));x.add(pass);m.instructions.insert(x);}
 static boolean magicPort(MethodInsnNode call){for(var n=call.getPrevious();n!=null;n=n.getPrevious())if(n instanceof LdcInsnNode ldc&&ldc.cst instanceof String text)return text.equals("(L"+PC+"$MassSlowCompanionTarget;II)I");return false;}
 static void patch(ClassNode c){
  if(c.name.equals(P+"NativeShockCompanionAction")){var old=c.methods.stream().filter(m->m.name.equals("shock")).findFirst().orElseThrow();old.name="nativeSourceControlledOriginalShock";var w=new MethodNode(old.access,"shock",old.desc,null,old.exceptions.toArray(String[]::new));for(int i=0;i<4;i++)w.instructions.add(new VarInsnNode(ALOAD,i));w.instructions.add(new MethodInsnNode(INVOKESTATIC,N,"shock",old.desc,false));w.instructions.add(new InsnNode(IRETURN));c.methods.add(w);return;}
  if(c.name.equals(P+"CombatCompanionSpells")){int count=0;for(var m:c.methods)if(Set.of("nativeShockCompanionBody","commitTargets").contains(m.name))for(var node:m.instructions)if(node instanceof MethodInsnNode call&&call.owner.equals(P+"CombatAccess")&&call.name.equals("integerCall")&&magicPort(call)){call.owner=N;call.name="invokeMagic";count++;}if(count!=2)throw new AssertionError("two existing reflective controlled magic HP ports "+count);return;}

  if(c.name.equals(P+"BattleCompanion")||c.name.equals(P+"NativeCompanionPlacement$State")){var wanted=c.name.endsWith("$State")?Set.of("master","scene","pose"):Set.of("active","x","y","hp","carriedItems");int n=0;for(var f:c.fields)if(wanted.contains(f.name)){f.access|=ACC_VOLATILE;n++;}if(n!=wanted.size())throw new AssertionError("readonly wire field visibility");return;}
  if(c.name.equals(CTX)){c.fields.add(new FieldNode(ACC_VOLATILE,FIELD(),"Ljava/lang/Object;",null,null));int count=0;for(var m:c.methods)if(m.name.equals("<init>"))for(var node:m.instructions.toArray())if(node.getOpcode()==RETURN){var x=new InsnList();x.add(new VarInsnNode(ALOAD,0));boolean copy=m.desc.equals("(L"+CTX+";)V");if(copy)x.add(new VarInsnNode(ALOAD,1));x.add(new MethodInsnNode(INVOKESTATIC,N,"inherit","(L"+CTX+";"+(copy?"L"+CTX+";":"")+")V",false));m.instructions.insertBefore(node,x);count++;}if(count!=2)throw new AssertionError("two actual context constructors");return;}
  if(c.name.equals(AREA)){var old=c.methods.stream().filter(m->m.name.equals("captureOutput")).findFirst().orElseThrow();old.name="nativeSourceControlledOriginalCaptureOutput";var w=new MethodNode(old.access,"captureOutput",old.desc,null,old.exceptions.toArray(String[]::new));for(int i=0;i<3;i++)w.instructions.add(new VarInsnNode(ALOAD,i));w.instructions.add(new MethodInsnNode(INVOKESTATIC,N,"captureOutput",old.desc,false));var prior=new LabelNode();w.instructions.add(new JumpInsnNode(IFEQ,prior));w.instructions.add(new InsnNode(ICONST_1));w.instructions.add(new InsnNode(IRETURN));w.instructions.add(prior);for(int i=0;i<3;i++)w.instructions.add(new VarInsnNode(ALOAD,i));w.instructions.add(new MethodInsnNode(INVOKESTATIC,AREA,old.name,old.desc,false));w.instructions.add(new InsnNode(IRETURN));c.methods.add(w);return;}
  int roots=0,phys=0,magic=0,center=0,fx=0,miss=0;for(var m:List.copyOf(c.methods)){if(m.name.equals("nativeStaticOriginalFrame"))guard(m);if(!root(m))continue;
   for(var node:m.instructions.toArray())if(node instanceof MethodInsnNode call){
    if(call.owner.equals(PC)&&call.name.equals("applyBattleCompanionFeedbackDamage")){var x=new InsnList();x.add(new VarInsnNode(ALOAD,0));if(m.name.equals("attack"))for(int slot:new int[]{39,113,144})x.add(new VarInsnNode(ALOAD,slot));m.instructions.insertBefore(call,x);call.owner=N;call.name=m.name.equals("attack")?"physical":"centered";call.desc="(L"+PC+";L"+P+"BattleCompanion;ILjava/util/List;Ljava/lang/String;L"+PC+";"+(m.name.equals("attack")?"L"+P+"SourceWeaponPhysicalStats;L"+P+"BattleWeaponCritical$RollOutcome;L"+P+"BattleWeaponCritical$DamageOutcome;":"")+")L"+P+"BattleCompanion$Damage;";call.setOpcode(INVOKESTATIC);if(m.name.equals("attack"))phys++;else if(Set.of("useCenteredAreaAttackSpell","nativeFreezeAcceptedOriginalBattle").contains(m.name))center++;else throw new AssertionError("unreviewed direct damage producer");
    }else if(call.owner.equals(PC)&&call.name.equals("applyBattleSpellCompanionDamage")){call.owner=N;call.name="magic";call.desc="(L"+PC+";Ljava/lang/Object;II)I";call.setOpcode(INVOKESTATIC);magic++;}
    else if(m.name.equals("attack")&&call.owner.equals(P+"NativeSourceNpcDamageDisplay")&&call.name.equals("kiringku")){m.instructions.insertBefore(call,new VarInsnNode(ALOAD,14));call.desc=call.desc.replace(")V","Ljava/lang/Object;)V");call.owner=N;fx++;}
    else if(m.name.equals("attack")&&call.owner.equals(P+"NativeSourceDamageDisplay")&&call.name.equals("miss")){m.instructions.insertBefore(call,new VarInsnNode(ALOAD,14));call.desc=call.desc.replace(")V","Ljava/lang/Object;)V");call.owner=N;miss++;}
   }wrapper(c,m);roots++;
  }if(roots!=8||phys!=1||magic!=3||center!=2||fx!=1||miss!=1)throw new AssertionError("reviewed roots/physical/magic/center/FX/miss "+roots+"/"+phys+"/"+magic+"/"+center+"/"+fx+"/"+miss);
 }
 static String FIELD(){return "nativeSourceControlledAction";}
 public static void main(String[] a)throws Exception{var urls=new ArrayList<java.net.URL>();urls.add(Path.of(a[1]).toUri().toURL());try(var files=Files.list(Path.of(a[3]))){for(var p:files.filter(p->p.toString().endsWith(".jar")).toList())urls.add(p.toUri().toURL());}try(var hierarchy=new java.net.URLClassLoader(urls.toArray(java.net.URL[]::new),ClassLoader.getPlatformClassLoader());var base=new JarFile(a[1])){FreezeAcceptedMethods.hierarchy=hierarchy;for(var name:TARGETS){var c=FreezeAcceptedMethods.read(base,name);patch(c);var canonical=new ClassNode();new ClassReader(FreezeAcceptedMethods.bytes(c,true)).accept(canonical,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);byte[] bytes=FreezeAcceptedMethods.bytes(canonical,false);if(a[0].equals("splice")){var p=Path.of(a[2]).resolve(name+".class");Files.createDirectories(p.getParent());Files.write(p,bytes);}else try(var next=new JarFile(a[2])){if(!Arrays.equals(bytes,FreezeAcceptedMethods.bytes(FreezeAcceptedMethods.read(next,name),false)))throw new AssertionError(name);}}}System.out.println("PASS9 controlled action roots including pre-pair87 and2 reflective magic ports,1 physical+3 targeted magic+2 centered/freeze HP ports, FX/miss and existing final receiver guard");}
}
